import { test, expect } from '@playwright/test';

test.describe('Dropdown Close on Escape Key Press', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dropdown');
  });

  test('should close dropdown when Escape key is pressed', async ({ page }) => {
    // Open dropdown using role-based locator
    const dropdownMenu = page.getByRole('menu');
    await dropdownMenu.click();

    // Verify dropdown is visible
    await expect(dropdownMenu).toBeVisible();

    // Verify dropdown content is visible
    const dropdownItems = page.getByRole('option');
    await expect(dropdownItems).toBeVisible();

    // Get the Escape key using getByRole
    const escapeKey = page.getByRole('keyboard-tab', { name: 'Escape' });

    // Verify Escape key is focused
    await expect(escapeKey).toBeFocused();

    // Press Escape key
    await escapeKey.press('Escape');

    // Verify dropdown is closed
    await expect(dropdownMenu).not.toBeVisible();

    // Verify dropdown content is no longer visible
    await expect(dropdownItems).not.toBeVisible();

    // Verify page content is restored
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();
  });

  test('should not close dropdown when Escape is pressed while typing in an input', async ({ page }) => {
    // Open dropdown using role-based locator
    const dropdownMenu = page.getByRole('menu');
    await dropdownMenu.click();

    // Verify dropdown is visible
    await expect(dropdownMenu).toBeVisible();

    // Get the Escape key using getByRole
    const escapeKey = page.getByRole('keyboard-tab', { name: 'Escape' });

    // Verify Escape key is focused
    await expect(escapeKey).toBeFocused();

    // Press Escape key
    await escapeKey.press('Escape');

    // Verify dropdown remains open
    await expect(dropdownMenu).toBeVisible();

    // Verify dropdown content is still visible
    const dropdownItems = page.getByRole('option');
    await expect(dropdownItems).toBeVisible();

    // Get input using getByLabel
    const searchInput = page.getByLabel('Search');

    // Type in the input
    await searchInput.fill('test');

    // Verify input is focused
    await expect(searchInput).toBeFocused();

    // Verify dropdown content is still visible
    await expect(dropdownItems).toBeVisible();

    // Verify Escape key does not close dropdown when typing
    await expect(escapeKey).toBeFocused();
  });
});
